page_settings.custom_css:
html{overflow-x:hidden}
body{overflow-x:hidden;max-width:100vw}
.elementor img,.elementor video{max-width:100%;height:auto}
.elementor-element{max-width:100%}
.cc-inner{width:100%!important;margin-left:auto!important;margin-right:auto!important;box-sizing:border-box}
.cc-mw-1140{max-width:1140px}
.cc-mw-1100{max-width:1100px}
.cc-mw-960{max-width:960px}
.cc-mw-900{max-width:900px}
.cc-mw-820{max-width:820px}
.cc-mw-760{max-width:760px}
.cc-mw-720{max-width:720px}
.cc-mw-680{max-width:680px}
@media(max-width:767px){.cc-inner{max-width:100%!important}}
.cc-num-circle{width:64px!important;height:64px!important;min-width:64px!important;min-height:64px!important;max-width:64px!important;max-height:64px!important;border-radius:50%!important;flex:0 0 64px!important;aspect-ratio:1/1!important;padding:0!important}
.cc-num-circle>.e-con-inner{width:100%!important;height:100%!important;display:flex!important;align-items:center!important;justify-content:center!important;padding:0!important}
.cc-topbar{padding-top:10px!important;padding-bottom:10px!important}
.cc-topbar .elementor-button{white-space:normal!important;line-height:1.15!important}
@media(max-width:767px){
 .cc-topbar{gap:10px!important;flex-wrap:nowrap!important;padding-left:12px!important;padding-right:12px!important;justify-content:space-between!important}
 .cc-topbar .elementor-button-wrapper{flex-shrink:0}
 .cc-topbar .elementor-button{font-size:10px!important;padding:7px 12px!important;line-height:1.15!important;white-space:normal!important;max-width:150px!important;text-align:center!important}
 .cc-topbar .elementor-heading-title{font-size:14px!important;white-space:nowrap}
 .cc-topbar p{font-size:9px!important;white-space:nowrap}
}

/* Topbar button BR: visivel so no mobile */
@media(min-width:768px){.cc-topbar .elementor-button br{display:none}}
/* Topbar alinhamento vertical */
.elementor-element-a000003{align-items:center!important}
.elementor-element-a000003 .e-con-inner{align-items:center!important}
.elementor-element-a000001 .elementor-widget-container,.elementor-element-a000002 .elementor-widget-container{display:flex!important;align-items:center!important;height:100%!important;padding:0!important}
